{"path": "/tmp/sv-090b442ff9804307b8e4fcd3dd148a9b/Components/Catalog/CatalogPagination.razor", "file_text": "<nav class="catalog-pagination" aria-label="Product pages">
    <button class="page-btn"
            disabled="@(CurrentPage <= 1)"
            @onclick="@(() => GoToPage(CurrentPage - 1))">
        Previous
    </button>

    @for (int i = 1; i <= TotalPages; i++)
    {
        var page = i;
        <button class="page-btn @(page == CurrentPage ? "active" : "")"
                @onclick="@(() => GoToPage(page))">
            @page
        </button>
    }

    <button class="page-btn"
            disabled="@(CurrentPage >= TotalPages)"
            @onclick="@(() => GoToPage(CurrentPage + 1))">
        Next
    </button>
</nav>

@code {
